/* V17 Enterprise Infrastructure & Hybrid Identity — original teaching material, no new infrastructure. */
(function(){
const lessons=[["hardware","Computer anatomy","Foundation","https://learn.microsoft.com/en-us/windows-server/get-started/","A server is a computer providing services, not a special kind of identity. Its OS schedules programs and manages resources.",[["CPU","Central processing unit executes machine instructions; cores allow concurrent execution. A saturated CPU can delay authentication processing."],["RAM","Volatile working memory for running programs and caches; contents do not persist when power is removed."],["Disk","Persistent storage for operating systems, databases and logs. Free space and latency affect directory service health."],["Process","Running instance of a program with its own execution state and allocated resources."],["Service","Long-running managed program, often started by the operating system without interactive login."],["Operating system","Software coordinating hardware, processes, memory, files and network access; Windows Server can host directory services."]],["Power and firmware initialize the machine.","The OS loads drivers, allocates memory and starts services.","A directory service reads records from persistent storage and uses RAM/CPU to answer requests.","A client receives the service response over the network."],"In Task Manager compare CPU, memory and disk activity; a service can be running but responding slowly. A process ID identifies a running instance, not an Entra object ID.","If all users experience latency, compare service health and server resource metrics before changing identities.","Which resource contains a running program's temporary working data?",["RAM","DNS zone","Security group"],0,"RAM holds working data; persistent files remain on disk."],["network","Networking engineering","Foundation","https://learn.microsoft.com/en-us/windows-server/networking/","A request travels across layers. Network delivery, encrypted transport and identity authorization solve different problems.",[["MAC address","Link-layer address used on a local network segment; routers forward IP packets between networks."],["IP address","Logical network address used to identify a network interface for packet routing."],["Subnet","Range of IP addresses sharing a network prefix. CIDR /24 means 24 bits are the network prefix."],["Default gateway","Router a host uses to reach destinations outside its local network."],["TCP","Connection-oriented reliable byte stream; used by HTTPS, among other applications."],["UDP","Connectionless datagrams without TCP's delivery guarantees; many DNS queries use UDP, with TCP also supported."],["Port","Transport-layer number identifying a service endpoint on a host. HTTPS commonly uses TCP 443."],["Firewall","Rule-based traffic control at a host or network boundary; allowing a port does not grant application permissions."]],["Client determines whether destination is on its own subnet.","For a remote destination, client sends a frame toward its gateway.","Routers forward packets; firewalls evaluate allowed traffic.","TCP connection and TLS establish a protected application channel before an identity request."],"Example 192.168.10.25/24 is in network 192.168.10.0/24. A target 192.168.20.10 normally requires routing. Test-NetConnection host -Port 443 tests TCP reachability, not whether sign-in will succeed.","Compare ipconfig /all, Resolve-DnsName and Test-NetConnection; ping failure alone does not establish TCP failure.","A remote sign-in endpoint resolves correctly but TCP 443 fails. Which layer should you investigate?",["Routing/firewall/connectivity","Group membership only","Access review expiration"],0,"DNS succeeded; the next failure is transport reachability."],["dns","DNS and DHCP","Foundation / SC-300 support","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds","Directory clients must find domain controllers, and devices must obtain usable network configuration.",[["DNS zone","Administrative collection of DNS records for a namespace."],["A/AAAA record","Maps a hostname to an IPv4/IPv6 address respectively."],["SRV record","Advertises a service endpoint, priority, weight and port. AD uses SRV records for controller location."],["CNAME","Alias pointing to another DNS name, not directly to an IP address."],["TXT record","Text data used for purposes including domain ownership verification."],["DHCP scope","Range and options from which a DHCP server assigns client network settings."],["Lease","Time-limited IP configuration granted to a client; DHCP also commonly supplies DNS and gateway options."]],["Client receives IP, gateway and DNS settings, often via DHCP.","Client queries its configured DNS resolver for domain service records.","Resolver locates the matching record and returns a domain controller target.","Client resolves that target and attempts directory authentication."],"Read-only example: Resolve-DnsName -Type SRV _ldap._tcp.dc._msdcs.contoso.example. A result contains NameTarget and Port. In a real AD environment, internal DNS must resolve AD service records.","Check the client DNS server, correct internal zone, SRV registration and connectivity; domain join can fail even while public websites work.","Which record helps a domain client discover a domain controller's LDAP service?",["MX","SRV","TXT"],1,"SRV advertises the service target and port."],["vm","Virtualization and Hyper-V","Foundation","https://learn.microsoft.com/en-us/windows-server/virtualization/hyper-v/overview","Virtualization allows isolated lab computers on one physical host without requiring separate physical servers.",[["Host","Physical computer running the virtualization platform."],["Hypervisor","Layer controlling virtual CPUs, memory and device access for virtual machines."],["Guest","OS running within a virtual machine, with its own logical hardware and network identity."],["VHDX","Virtual hard disk file used by Hyper-V to store guest disk data."],["Virtual switch","Software network switch connecting VM network adapters; external/internal/private modes determine connectivity."],["Checkpoint","Point-in-time VM state mechanism; not a substitute for a validated backup strategy."]],["Host assigns resources to the VM.","Hypervisor presents virtual hardware to the guest.","Guest starts its OS and attaches a virtual adapter to a switch.","Guest communicates according to its network configuration and switch topology."],"A safe lab could use an isolated internal/private virtual network with a fictional domain controller and client. Internet access and cloud synchronization require separate approved configuration. Do not connect an experimental DHCP server to a production LAN.","Check virtual adapter/switch attachment, guest IP settings, host resources and guest services independently.","A VM can start but cannot reach another VM on its intended isolated network. What should you inspect first?",["Virtual switch and guest IP settings","Entra access packages","Mailbox delegation"],0,"Network attachment and addressing determine guest connectivity."],["server","Windows Server administration","Foundation","https://learn.microsoft.com/en-us/windows-server/administration/","Windows Server provides operating-system capabilities on which directory, DNS, file and management services run.",[["Role","Server capability such as AD DS or DNS Server, installed and configured for a specific workload."],["Feature","Supporting OS capability installed as needed; not necessarily a server role."],["Event Viewer","Tool that reads Windows event logs, including system, application and role-specific records."],["Service account","Identity used by a service; use scoped rights and managed service accounts when supported."],["PowerShell cmdlet","Verb-Noun command that typically emits structured objects."],["RSAT","Remote Server Administration Tools for administering supported Windows Server roles from a management workstation."]],["Install only required server roles and dependencies.","Configure networking and role-specific settings.","Run the role service and monitor event logs.","Administer remotely using appropriate permissions and verify actual service behavior."],"Get-Service -Name DNS reads DNS service status if installed; Get-WinEvent -LogName System -MaxEvents 20 reads recent system events with appropriate rights. Service running does not prove its configuration is correct.","Check recent changes, event IDs, role state, service dependencies and reachability; avoid restarting services indiscriminately.","Which evidence identifies a service startup failure more directly?",["System or application event logs","An unrelated user's UPN","The Teams display name"],0,"Windows logs can show the service-specific startup error."],["ad","Active Directory anatomy","SC-300 user identities","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/virtual-dc/active-directory-domain-services-overview","AD DS is an on-premises directory and domain authentication system. Entra ID is a separate cloud identity system.",[["Forest","Top-level AD DS structure containing one or more domains that share schema and configuration; primary AD security boundary."],["Domain","Logical partition with its own directory namespace and domain controller replicas."],["Tree","One or more domains in a contiguous DNS namespace within a forest."],["OU","Organizational unit: directory container for organizing objects, delegating administration and linking GPOs."],["Domain controller","Server running AD DS that authenticates domain identities and holds directory replicas."],["Distinguished name","Directory object's hierarchical LDAP name, e.g. CN=Alex,OU=IT,DC=contoso,DC=example."],["SID","Security identifier used by Windows authorization; not the same as an object's GUID or cloud object ID."],["Schema","Definitions of supported directory object classes and attributes."]],["AD DS forest and domain provide the directory structure.","Admin creates a user object in an appropriate OU.","Domain controller authenticates identity and group membership participates in authorization.","Resource checks its ACL and the user's security context."],"A user has sAMAccountName alex, UPN alex@contoso.example, objectGUID and objectSID. OU membership is not security group membership. Moving a user to a different OU can change GPO or sync scope without granting a file permission.","Use read-only Get-ADUser with appropriate RSAT and rights; compare DN, UPN, Enabled and memberships. Verify target resource permission separately.","Which structure is used to link a GPO to a selected collection of directory objects?",["OU","User SID","Individual TCP port"],0,"GPOs can be linked to sites, domains and OUs; an OU is the relevant organizational container."],["kerberos","Windows authentication and authorization","SC-300 hybrid foundation","https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-authentication-overview","Windows domain sign-in and service access use protocols different from OAuth cloud API tokens.",[["Kerberos","Ticket-based authentication protocol used in AD domains; relies on trusted key distribution and time alignment."],["KDC","Key Distribution Center on domain controllers, providing authentication and ticket-granting services."],["TGT","Ticket-granting ticket used to request service tickets without re-entering the password."],["SPN","Service Principal Name identifying a service instance for Kerberos ticket requests."],["Service ticket","Ticket for a specific service, presented to that service for authentication."],["NTLM","Older challenge-response authentication protocol; avoid unnecessary reliance and follow current hardening guidance."],["LDAP","Protocol for querying and modifying directory information; LDAP itself is not Kerberos."],["ACL","Access control list defining allowed or denied access for security principals."]],["Client locates domain controller and requests initial authentication.","KDC issues a TGT after successful authentication.","Client requests a service ticket for the service SPN.","Client presents ticket to service; resource evaluates authorization separately."],"For a fictional file server cifs/files.contoso.example, the SPN identifies the service. klist displays cached Kerberos tickets on Windows; a ticket for one service does not automatically authorize access to another.","Check domain DNS, time synchronization, SPN registration, ticket cache and resource ACL. Avoid disabling modern security merely to make a legacy protocol work.","What does a TGT enable a client to request?",["A service ticket from the KDC","A new Microsoft 365 subscription","An unrestricted filesystem ACL"],0,"A TGT is used to request service-specific tickets."],["replication","AD replication and FSMO","SC-300 hybrid foundation","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/troubleshoot/troubleshooting-active-directory-replication-problems","Multiple domain controllers share directory changes; some specialized operations use single-master roles.",[["Replication","Propagation of directory changes between domain controllers; delays or failures can produce temporarily inconsistent views."],["Site","AD topology representation of network locations, associated with IP subnets to guide controller selection and replication."],["Global Catalog","Domain controller with a searchable partial replica of objects across the forest plus its local domain data."],["FSMO","Flexible Single Master Operations: five roles coordinating particular operations requiring one role owner."],["RID master","Allocates RID pools to domain controllers for creating unique domain security identifiers."],["PDC emulator","Domain role important for time hierarchy, password-related behavior and other compatibility functions."],["SYSVOL","Replicated share containing Group Policy files and scripts; modern domains use DFS Replication for SYSVOL."],["DFSR","Distributed File System Replication; separate from directory object replication."]],["A writable controller commits an object update.","Replication topology determines partners and timing.","Partner controller receives the directory change.","Client or sync engine reads the replica; if stale, it may see the old data."],"Five FSMO roles: Schema Master and Domain Naming Master (forest-wide); RID Master, PDC Emulator and Infrastructure Master (per domain). Read-only diagnostics include repadmin /replsummary and dcdiag with proper access.","Check replication failures, DNS, connectivity, time, event logs and SYSVOL separately. Do not seize FSMO roles as routine troubleshooting.","A user appears on DC1 but not DC2 shortly after creation. What should you verify?",["Replication convergence and health","Microsoft 365 billing cycle","The user's Outlook signature"],0,"The controllers may not yet have converged or replication may be failing."],["gpo","Group Policy and effective access","Foundation / MD-102 support","https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-overview","Central Windows policies are distinct from Entra Conditional Access, Intune compliance and file ACLs.",[["GPO","Group Policy Object containing Windows settings with directory and SYSVOL components."],["Link","Association of a GPO to a site, domain or OU; link location contributes to applicability."],["Security filtering","Controls which eligible security principals can read/apply a GPO."],["WMI filter","Condition evaluated on a client to determine applicability of a linked GPO."],["Inheritance","Policy application from parent containers, affected by precedence and specific controls."],["Resultant Set of Policy","Effective policy results for a user or computer; gpresult reports applied settings and policy information."],["NTFS permission","File-system ACL permission; remote SMB access must also satisfy share permissions."]],["Client locates domain controller and receives applicable policy list.","Local, site, domain and OU processing plus filtering determine applicable GPOs.","Client-side extensions apply relevant settings under policy rules.","Administrator verifies actual resulting policy and resource access."],"gpresult /r reports applied GPOs for the relevant context. If a drive mapping is missing, check user vs computer configuration, link location, filtering and SYSVOL before editing the policy.","Compare expected OU and actual GPO results; consider Intune policy separately. Do not assume group membership alone applies an unlinked GPO.","Which tool helps show the policies actually applied to a Windows user/computer?",["gpresult","nslookup only","Microsoft Graph consent screen"],0,"gpresult reports effective Group Policy information."],["sync","Hybrid directory synchronization","SC-300 user identities","https://learn.microsoft.com/en-us/entra/identity/hybrid/cloud-sync/connect-to-cloud-sync-decision-guide","Synchronization moves supported identity data between directories. It is not the same operation as authenticating a password.",[["Connect Sync","Microsoft Entra Connect Sync uses a synchronization engine and configured connectors/rules on a server."],["Cloud Sync","Agent-based provisioning with cloud-managed configuration; choose using Microsoft's current capabilities and topology comparison."],["Source anchor","Stable identifier used to associate an on-premises object with its corresponding cloud identity."],["Immutable ID","Cloud-side representation of the association for applicable synchronized identities, often represented in onPremisesImmutableId."],["Sync scope","Configured selection of objects eligible for synchronization; an excluded OU or filter prevents inclusion."],["Attribute mapping","Rule translating or flowing directory properties between source and target."],["Source of authority","System governing a given object or attribute; cloud edits may be restricted or overwritten for synchronized objects."],["Matching","Association with an existing cloud identity; verify matching rules and collision handling before deployment."]],["Read source AD object and configured scope.","Synchronization engine evaluates rules, mapping and identity matching.","Export accepted changes to the cloud directory.","Verify the cloud object and logs; assign cloud resource authorization separately."],"Example: Alex exists under OU=Employees with UPN alex@contoso.example and source anchor A1. A new cloud object or existing matched object must retain the intended association. Duplicate UPN or proxy address can block provisioning. Never casually change anchors to force matching.","Check source object, replication, connector/agent health, OU filters, export/provisioning errors, verified UPN suffix and duplicate attributes. Use current Microsoft migration guide; avoid overlapping sync scope.","An AD user is in an excluded OU. What is the first reason it does not appear in Entra?",["Sync scope excludes the object","PIM is not activated","The user's desktop wallpaper"],0,"The object is not eligible for synchronization until approved scope is corrected."],["hybauth","Hybrid authentication methods","SC-300 authentication","https://learn.microsoft.com/en-us/entra/identity/hybrid/connect/choose-ad-authn","Choose where credentials are validated independently of selecting a directory synchronization engine.",[["PHS","Password Hash Synchronization: cloud validates against synchronized derived password hashes, not plaintext passwords."],["PTA","Pass-through Authentication: on-premises agents validate password requests against AD; agent availability and AD connectivity matter."],["Federation","Identity trust redirects authentication to a configured external identity provider; availability depends on the federation architecture."],["Seamless SSO","Optional capability using Kerberos in supported domain-connected scenarios to reduce credential prompts; distinct from sync."],["Staged rollout","Controlled testing of selected cloud authentication methods for eligible users before a broader domain change."],["Password writeback","Supported feature allowing eligible cloud password changes/resets to flow back to on-premises AD when configured and licensed."]],["User starts cloud sign-in; Entra determines configured authentication path.","PHS validates in cloud; PTA sends validation to an available on-prem agent; federation uses its identity provider.","Entra applies relevant authentication and access controls for the requested resource.","Resource receives a token and evaluates its own authorization."],"If a cloud password hash is current, PHS can authenticate during an on-prem network outage; PTA without reachable agents cannot validate new password sign-ins in this simplified scenario. Existing sessions and alternative methods complicate real outcomes. PHS is not automatically failover unless planned/configured.","Verify configured method, sync freshness, agent health or federation reachability, sign-in details, rollback and emergency access. Never disable broad security controls to bypass failures.","With a current synchronized hash, which method can validate a new cloud password sign-in without a live on-premises agent?",["PTA","PHS","Federation requiring on-prem IdP"],1,"PHS performs cloud password validation."],["devices","Hybrid device identity","SC-300 authentication / MD-102","https://learn.microsoft.com/en-us/entra/identity/devices/overview","Device identity, management and compliance are related but not equivalent.",[["AD domain joined","Windows device has a computer account and trust relationship with an AD domain."],["Entra registered","Device identity associated with a work/school account, commonly BYOD; not equivalent to Entra join."],["Entra joined","Device joined directly to Microsoft Entra ID; can use cloud identity for Windows sign-in."],["Entra hybrid joined","AD-domain-joined Windows device additionally joined to Entra; retains on-premises domain relationship."],["PRT","Primary Refresh Token used in supported device/user sign-in flows to enable SSO and identity context."],["SCP","Service Connection Point in AD used in certain hybrid join discovery configurations."],["MDM","Mobile Device Management, such as Intune enrollment; registration or join alone does not imply enrollment."],["Compliance","Evaluation against configured device requirements; can be consumed by Conditional Access."]],["Device joins AD or Entra as appropriate to its design.","Hybrid join discovery/registration establishes the corresponding Entra identity.","Supported user sign-in acquires device-bound SSO context such as a PRT where applicable.","Management evaluates compliance; Conditional Access consumes relevant signals."],"Read-only dsregcmd /status: AzureAdJoined=YES and DomainJoined=YES indicates hybrid join in this Windows context; a Pending cloud registration is not completed. Check DeviceId and AzureAdPrt in appropriate user context.","Inspect dsregcmd status, cloud device record, registration logs, connectivity, MDM and compliance as separate checks. Do not delete device objects without approved recovery plan.","A device is hybrid joined but Intune shows it noncompliant. Does hybrid join itself satisfy a compliant-device grant?",["Yes","No, compliance is separately evaluated","Yes if DomainJoined is YES"],1,"Join proves identity relationship, not compliance."],["security","Hybrid security and recovery","SC-300 / SC-100 support","https://learn.microsoft.com/en-us/entra/architecture/resilience-in-hybrid","Secure both sides of the trust boundary and retain independent recovery paths.",[["Trust boundary","Point where security assumptions, identity authority or control ownership changes between systems."],["Certificate","Signed binding between a public key and identity or subject; expiry and trust chains affect TLS/federation."],["Privileged access","Elevated permissions requiring least privilege, separation and monitoring; compromise can propagate across hybrid systems."],["Defender for Identity","Security solution using supported identity infrastructure telemetry to detect suspicious activity."],["Emergency access","Separately protected cloud emergency accounts designed and monitored for recovery from identity outages."],["System state backup","Supported Windows backup of critical system components including AD DS on a domain controller; recovery requires documented tested procedures."]],["Map identity authorities and privileged administration paths.","Harden on-prem servers, connectors, agents and cloud administrators.","Monitor identity events and validate conditional controls.","Test supported backup/recovery and emergency access in approved exercises."],"A certificate expiration in a federation service may prevent new sign-ins while some sessions continue. Separate certificate chain/expiry, IdP health and Entra policy diagnostics; use approved break-glass procedure if needed.","Collect relevant logs without sharing secrets; review risk, agent health, certificate expiry and backup evidence. Avoid changing domain-wide trust or security settings without authorization.","Why should emergency cloud access not depend solely on an on-prem authentication service?",["To preserve recovery access if that service fails","To make all users Global Administrator","To remove the need for auditing"],0,"Independent recovery paths reduce correlated failure risk."],["diagnose","End-to-end hybrid troubleshooting","SC-300 all domains","https://learn.microsoft.com/en-us/entra/identity/hybrid/connect/tshoot-connect-sync-errors","Find the first failing boundary before making an administrative change.",[["Symptom","Observable behavior reported by a user; not necessarily the cause."],["Scope","Which users, devices, resources or sites are affected."],["Evidence","Logs, timestamps, identifiers, status and reproducible observations used to test hypotheses."],["Provisioning log","Records provisioning operations and failures for supported services; distinguish from authentication logs."],["Sign-in log","Cloud authentication and access evaluation records, with client, resource and policy context where available."],["Correlation ID","Identifier useful for relating request diagnostics; combine with timestamp and resource."],["Remediation","Approved action correcting confirmed cause, followed by validation and documentation."]],["Collect symptom and scope; compare known-working path.","Check AD source and replication, then sync eligibility and export.","Check cloud object, credential method, device signal and Conditional Access.","Check resource permissions; validate allowed and denied operations."],"User exists in AD but not Entra: check authoritative object and sync scope/export first. User exists in Entra but fails sign-in: inspect authentication route and sign-in logs. User signs in but cannot open app: inspect assignment/resource authorization.","Use evidence at each boundary. Read-only tools: Get-ADUser, repadmin /replsummary, dsregcmd /status, Entra provisioning/sign-in logs. Use only authorized environments and accounts.","A user is present in Entra and successfully authenticates, but the application denies access. What next?",["Inspect enterprise app assignment and resource authorization","Rebuild all domain controllers","Change the source anchor"],0,"Successful authentication narrows the failure to later access checks."],["capstone","Enterprise hybrid capstone","SC-300 practical integration","https://microsoftlearning.github.io/SC-300-Identity-and-Access-Administrator/","Combine directory, sync, authentication, device and application permissions in one fictional workflow.",[["Joiner","New employee requiring correctly scoped identity and access."],["Mover","Employee whose role change requires obsolete permissions removed."],["Leaver","Departing identity whose access must be removed and retained data handled appropriately."],["Negative test","Proves an unauthorized action remains denied, not merely that an approved action succeeds."],["Audit trail","Sequence of recorded actions and outcomes supporting accountability."],["Evidence of mastery","Independent execution and explanation supported by validation; simulation is not an official exam or real tenant."]],["Create the fictional employee in AD with the correct OU and UPN.","Configure scope and run the modeled synchronization, verify cloud identity.","Choose authentication, device state and app assignment, evaluate access.","Inject faults and prove denial, restore approved settings, verify offboarding."],"Use the connected V17 lab to create a fictional employee, synchronize, authorize and then test failure modes. The simulator deliberately models only a subset of real AD/Entra behavior; official Microsoft labs remain necessary for real configuration.","Compare evidence after each stage; do not bypass policy to pass. Keep positive and negative tests and verify cloud access after offboarding.","What demonstrates least privilege better than successful access alone?",["Successful approved access and denied unrelated access","A permanent administrator role","A screenshot of a login page"],0,"Positive and negative tests establish modeled scope."]],cases=[["dns-missing","DNS discovery failure","A domain-joined laptop can browse public websites but cannot find its domain controller. Its configured DNS server is a public resolver.","Check internal AD DNS and the controller SRV records.","dns",["Reset cloud password","Check internal AD DNS and SRV records","Grant an Entra admin role"],1],["replica","Stale replica","A user created on DC1 cannot be found by a sync engine reading DC2. DC2 has a replication failure.","Verify replication and source read location before changing sync scope.","replication",["Recreate the user in Entra","Change its source anchor","Check DC replication and connector source"],2],["scope","Excluded OU","A user is present on both DCs but missing in Entra. Their OU is excluded in the sync configuration.","Confirm authorized inclusion and verify sync/export results.","sync",["Review configured scope","Turn off MFA","Change SharePoint permission"],0],["ptafail","PTA outage","New password sign-ins fail for a PTA-only pilot; all PTA agents are unavailable. Cloud-only emergency access is healthy.","Investigate agent health and approved resilience plan; do not assume automatic PHS failover.","hybauth",["Delete synchronized users","Check agent health and approved failover","Set all accounts to Global Administrator"],1],["device","Hybrid join vs compliance","A laptop shows AzureAdJoined and DomainJoined YES, but a compliant-device policy blocks access.","Verify Intune enrollment/compliance and relevant sign-in evidence; join is not compliance.","devices",["Check Intune compliance and sign-in policy","Delete the domain","Disable every Conditional Access policy"],0],["spn","Kerberos service failure","Domain login works; a file server fails Kerberos authentication. The service SPN is duplicated.","Investigate SPN ownership and correct through approved procedure.","kerberos",["Add an unrelated license","Investigate duplicate SPN","Reset all passwords"],1],["gpo","Missing policy","A user in Finance does not receive a mapped drive. gpresult shows the GPO is denied by filtering.","Review applicable link and security filtering.","gpo",["Change tenant ID","Rebuild the laptop","Review GPO filtering and scope"],2],["offboard","Residual access","A contractor's package expires but the application still allows access via another group.","Trace all remaining grants and remove only obsolete authorized access.","capstone",["Inspect alternate access grants","Renew all access","Ignore the result"],0]];
// Rotate answer positions deterministically before any learner progress exists.
lessons.forEach((l,i)=>{const k=(i+1)%3,old=l[10];l[10]=old.slice(k).concat(old.slice(0,k));l[11]=(l[11]+3-k)%3;});
const H=x=>String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const store='entra-v17-study-v1';
function freshLab(){return {user:false,enabled:true,ou:'Excluded',scope:'Employees',domain:'contoso.example',dns:true,replication:true,agent:true,method:'PHS',cloud:false,cloudEnabled:false,hash:false,device:'registered',compliant:false,assignment:'none',policy:true,logs:[],last:null,negative:null};}
function fresh(){return {last:'hardware',answers:{},cases:{},stages:{},cards:{},notes:{},lab:freshLab()};}
let s=fresh();try{let t=JSON.parse(localStorage.getItem(store)||'null');if(t&&typeof t==='object')s={...s,...t,lab:{...freshLab(),...t.lab}};}catch(e){}
function persist(){try{localStorage.setItem(store,JSON.stringify(s));}catch(e){toast('Progress could not be saved locally.');}}
const css='<style>.hy17{max-width:1150px;margin:auto}.hy17 h1,.hy17 h2{line-height:1.25}.hy17-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:12px}.hy17-panel{border:1px solid #b5c7d8;border-radius:13px;padding:18px;margin:12px 0;background:var(--panel,#fff);color:var(--text,#152c43)}.hy17-panel h3{margin:0 0 9px}.hy17-panel p,.hy17-panel li{line-height:1.6}.hy17-label{color:#1268a9;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.06em}.hy17-flow{display:flex;gap:8px;flex-wrap:wrap}.hy17-flow .btn{flex:1;min-width:120px}.hy17 .btn{white-space:normal;margin:4px}.hy17-on{outline:3px solid #1684d9}.hy17-output{padding:14px;margin:12px 0;background:#e8f3ff;color:#123451;border-left:4px solid #1876bc}.hy17-choice .btn{display:block;text-align:left;width:100%;box-sizing:border-box}.hy17 textarea{width:100%;min-height:100px;box-sizing:border-box}.hy17 code{white-space:normal;overflow-wrap:anywhere}.hy17 input{max-width:100%;padding:10px}.hy17-stat{font-size:24px;font-weight:700}.hy17-status{font-size:13px;font-weight:600}.hy17-log{max-height:320px;overflow:auto}.hy17 .hy17-controls{display:flex;flex-wrap:wrap;align-items:center}.hy17 .hy17-controls label{font-weight:700}.hy17 a{overflow-wrap:anywhere}</style>';
const btn=(route,label)=>'<button class="btn" data-route="'+H(route)+'">'+H(label)+'</button>';
const act=(action,id,label,extra='',on=false)=>'<button class="btn '+(on?'hy17-on':'')+'" data-action="'+H(action)+'" data-id="'+H(id)+'" '+extra+'>'+H(label)+'</button>';
const p=x=>'<p>'+H(x)+'</p>',panel=(title,body)=>'<section class="hy17-panel"><h3>'+H(title)+'</h3>'+body+'</section>';
const link=(url,label)=>'<a href="'+H(url)+'" target="_blank" rel="noopener noreferrer">'+H(label)+'</a>';
const wrap=(body)=>'<div class="page hy17">'+css+body+'</div>';
const homeLink=()=>btn('v17/home','← Hybrid academy');
const get=id=>lessons.find(l=>l[0]===id);
const score=()=>lessons.filter(l=>s.answers[l[0]]===l[11]).length;
const caseScore=()=>cases.filter(c=>s.cases[c[0]]===c[6]).length;
const vocab=lessons.flatMap(l=>l[5].map((t,i)=>({id:l[0]+'-'+i,lesson:l[0],name:t[0],def:t[1]})));
const cardDue=()=>vocab.filter(t=>!s.cards[t.id]||s.cards[t.id].due<=Date.now());
let revealed='',filter='',cursor=0;
const oldRender=render,oldShell=shell,oldAction=action;
shell=(content,where)=>oldShell(content,where).replace('<div class="sidefoot">','<div class="sectioncap">V17 · Enterprise infrastructure</div><button class="navitem" data-route="v17/home">▣ Hybrid learning track</button><button class="navitem" data-route="v17/lab">▣ Hybrid identity simulator</button><button class="navitem" data-route="v17/cards">▣ Vocabulary recall</button><div class="sidefoot">');
function home(){return wrap('<div class="hy17-label">V17 · From hardware to cloud identity</div><h1>Enterprise Infrastructure &amp; Hybrid Identity Engineering</h1>'+p('Build the complete mental model: computer → network → Windows Server → AD DS → sync → Entra → application access. Start from zero or follow the exam-focused hybrid path.')+panel('Your evidence','<div class="hy17-grid"><div class="hy17-stat">'+score()+'/'+lessons.length+' lesson checks</div><div class="hy17-stat">'+caseScore()+'/'+cases.length+' case decisions</div><div class="hy17-stat">'+cardDue().length+' vocabulary cards due</div></div>'+p('Self-study results are not exam readiness. The lab tracks simulated configuration and validation separately.')+btn('v17/lesson/'+(get(s.last)?s.last:'hardware'),'Resume lesson')+btn('v17/lab','Open hybrid simulator')+btn('v17/cards','Recall vocabulary')+btn('v17/cases','Troubleshooting casebook'))+'<h2>15 learning modules</h2><div class="hy17-grid">'+lessons.map((l,i)=>panel((i+1)+'. '+l[1],'<div class="hy17-label">'+H(l[2])+'</div>'+p(l[4])+btn('v17/lesson/'+l[0],s.answers[l[0]]===l[11]?'Review':'Study'))).join('')+'</div>'+panel('Certification and further practice',btn('v16/home','V16 Microsoft 365 engineering')+btn('v15/vocabulary','V15 identity microscope')+btn('v12/missions','Existing Entra state-checked missions')+'<p>'+link('https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/sc-300','Official SC-300 study guide')+' · '+link('https://microsoftlearning.github.io/SC-300-Identity-and-Access-Administrator/','Official labs')+' · '+link('https://github.com/Irfaanpk/Microsoft-Hybrid-Cloud-Zero-to-Hero','Supplementary Irfaanpk curriculum reference')+'</p>'+p('Independent original lessons; the external repository is linked, not copied. Real Microsoft labs may require approved licenses or a lab tenant. No actual cloud resources are provisioned.')));}

function lesson(l){const i=lessons.indexOf(l),step=Math.max(0,Math.min(3,s.stages[l[0]]||0)),a=s.answers[l[0]];return wrap(homeLink()+'<div class="hy17-label">Module '+(i+1)+' · '+H(l[2])+'</div><h1>'+H(l[1])+'</h1>'+panel('Why and when does it matter?',p(l[4]))+'<h2>Micro vocabulary · What each thing is and does</h2><div class="hy17-grid">'+l[5].map(t=>panel(t[0],p(t[1]))).join('')+'</div>'+panel('How it works · Click through the system','<div class="hy17-flow">'+l[6].map((v,n)=>act('hy17-stage',l[0],'Stage '+(n+1),'data-value="'+n+'"',n===step)).join('')+'</div><div class="hy17-output"><b>Stage '+(step+1)+' of 4</b>'+p(l[6][step])+'</div>')+panel('Under the microscope · Example and technical detail',p(l[7]))+panel('Troubleshooting · What to inspect and why',p(l[8]))+panel('Test yourself',p(l[9])+'<div class="hy17-choice">'+l[10].map((v,n)=>act('hy17-answer',l[0],v,'data-value="'+n+'"',a===n)).join('')+'</div>'+(Number.isInteger(a)?'<div class="hy17-output"><b>'+(a===l[11]?'Correct':'Not yet')+'</b>'+p(l[12])+'</div>':''))+panel('Teach it back','<p>Explain the purpose, internals, dependency and one failure from memory.</p><form id="hy17-note" data-id="'+H(l[0])+'"><textarea name="note" aria-label="Your explanation">'+H(s.notes[l[0]]||'')+'</textarea><button class="btn primary" type="submit">Save reflection</button></form>')+panel('Official source and practice','<p>'+link(l[3],'Microsoft documentation')+'</p>'+btn('v17/cards','Recall vocabulary')+btn('v17/lab','Practice hybrid workflow')+btn('v17/cases','Diagnose failures'))+'<div class="flex wrap">'+(i?btn('v17/lesson/'+lessons[i-1][0],'Previous lesson'):'')+(i<lessons.length-1?btn('v17/lesson/'+lessons[i+1][0],'Next lesson →'):btn('v17/lab','Start capstone →'))+'</div>');}
function casebook(){return wrap(homeLink()+'<h1>Hybrid diagnostic casebook</h1>'+p('Choose a first action based on evidence. These fictional cases do not modify an actual tenant.')+cases.map(c=>panel(c[1],p(c[2])+'<div class="hy17-choice">'+c[5].map((v,n)=>act('hy17-case',c[0],v,'data-value="'+n+'"',s.cases[c[0]]===n)).join('')+'</div>'+(Number.isInteger(s.cases[c[0]])?'<div class="hy17-output"><b>'+(s.cases[c[0]]===c[6]?'Correct':'Not yet')+'</b>'+p(c[3])+'</div>':'')+btn('v17/lesson/'+c[4],'Review supporting lesson'))).join(''));}
function cards(){const due=cardDue(),list=(filter==='all'?vocab:due),t=list.find(x=>x.id===revealed)||list[cursor%Math.max(1,list.length)];return wrap(homeLink()+'<h1>Vocabulary recall studio</h1>'+p('Try explaining the term aloud before revealing it. Mark again to retry now, or remembered to schedule the next local review. This is a simple spaced-review schedule, not validated mastery.')+'<p>'+due.length+' due · '+vocab.length+' total</p>'+act('hy17-card-mode','due','Due today','',filter!=='all')+act('hy17-card-mode','all','All terms','',filter==='all')+(t?panel(t.name, revealed===t.id?p(t.def)+act('hy17-rate',t.id,'Again','data-value="again"')+act('hy17-rate',t.id,'Remembered','data-value="good"')+btn('v17/lesson/'+t.lesson,'Read full lesson'):act('hy17-reveal',t.id,'Reveal meaning')):panel('Review complete',p('No cards due. Study another module or review all terms.'))));}
function event(l,message){l.logs.unshift(message);l.logs=l.logs.slice(0,40);}
function sync(l){if(!l.user){event(l,'SYNC: no source object');return false;}if(!l.dns||!l.replication||!l.agent){event(l,'SYNC: source discovery, replica or agent unhealthy');return false;}if(l.ou!==l.scope){event(l,'SYNC: source excluded by OU scope; existing cloud object not modified by this simplified model');return false;}if(l.domain!=='contoso.example'){event(l,'SYNC: unverified UPN suffix in this lab; repair before export');return false;}l.cloud=true;l.cloudEnabled=l.enabled;l.hash=true;event(l,'SYNC: cloud object HYB-U1 updated; enabled='+l.cloudEnabled+'; current derived hash modeled');return true;}
function access(l,target){let why;if(!l.cloud)why='Cloud identity missing';else if(!l.cloudEnabled)why='Cloud account disabled';else if(l.method==='PHS'&&!l.hash)why='No current synchronized password hash';else if(l.method!=='PHS'&&(!l.agent||!l.dns||!l.replication))why='On-prem authentication dependency unavailable';else if(l.policy&&(!l.compliant||l.device!=='hybrid'))why='Lab policy requires hybrid join and compliance';else if(l.assignment!==target)why='Target app not assigned';else why='Allowed';const result={target,allowed:why==='Allowed',why};if(target==='finance')l.negative=result;else l.last=result;event(l,'ACCESS '+target+': '+why);return result;}
function criteria(l){return [['Source AD object in Employees OU with verified UPN',l.user&&l.ou==='Employees'&&l.domain==='contoso.example'],['Scoped synchronization and cloud identity present',l.scope==='Employees'&&l.cloud&&l.cloudEnabled&&l.enabled],['Approved PHS and current modeled hash',l.method==='PHS'&&l.hash],['Hybrid device and compliant state',l.device==='hybrid'&&l.compliant],['Policy enforced and only Helpdesk assigned',l.policy&&l.assignment==='helpdesk'],['Current Helpdesk allowed and Finance denied',!!l.last?.allowed&&l.last.target==='helpdesk'&&!!l.negative&&!l.negative.allowed&&l.negative.target==='finance'&&l.negative.why==='Target app not assigned'&&l.cloudEnabled]];}
function change(l,k,v){if(!Object.hasOwn(l,k))return;if(k==='user'||k==='enabled'||k==='dns'||k==='replication'||k==='agent'||k==='compliant'||k==='policy')l[k]=v==='true';else l[k]=v;l.last=null;l.negative=null;event(l,'CONFIG '+k+' = '+String(l[k]));}
function lab(){let l=s.lab;const opts=(k,values)=>'<div class="hy17-controls"><label>'+H(k)+':</label>'+values.map(v=>act('hy17-config',k,v[1],'data-value="'+H(v[0])+'"',String(l[k])===v[0])).join('')+'</div>';const yesno=(k,a,b)=>opts(k,[['true',a],['false',b]]);return wrap(homeLink()+'<div class="hy17-label">Fictional state-based lab · no actual AD or Azure connection</div><h1>Contoso hybrid identity simulator</h1>'+p('Mission: onboard Alex, grant Helpdesk only, require hybrid compliant device, prove Finance is denied, then test outage and offboarding. Start with a missing user and deliberately incorrect OU. Configuration changes invalidate prior access test results.')+panel('1 · On-premises AD DS',yesno('user','Create Alex','No source user')+yesno('enabled','Enabled','Disabled')+opts('ou',[['Employees','Employees OU'],['Excluded','Excluded OU']])+opts('domain',[['contoso.example','Verified contoso.example'],['unknown.example','Unverified suffix']])+yesno('dns','DNS healthy','Inject DNS failure')+yesno('replication','Replication healthy','Inject replication failure')+p('Fictional DN: CN=Alex,OU='+l.ou+',DC=contoso,DC=example. Source anchor: HYB-A1. Account enabled changes take effect in this lab after sync.'))+panel('2 · Synchronization bridge',opts('scope',[['Employees','Employees OU'],['Excluded','Excluded OU']])+yesno('agent','Agent healthy','Inject agent outage')+act('hy17-sync','sync','Run modeled synchronization')+p('Cloud object: '+(l.cloud?'HYB-U1':'not provisioned')+' · Cloud enabled: '+l.cloudEnabled+' · Current derived hash: '+l.hash)+p('Scope removal does not model deletion here. Real sync engines have more detailed deprovisioning and matching behavior.'))+panel('3 · Authentication method and device',opts('method',[['PHS','Password hash sync'],['PTA','Pass-through'],['Federation','Federation (modeled on-prem dependency)']])+opts('device',[['registered','Registered'],['joined','Entra joined'],['hybrid','Hybrid joined']])+yesno('compliant','Compliant','Noncompliant')+p('This lab simulates new password sign-in only, not existing sessions, token lifetimes, MFA or automatic failover.'))+panel('4 · Cloud authorization and policy',opts('assignment',[['none','No app'],['helpdesk','Helpdesk only'],['finance','Finance only']])+yesno('policy','Require hybrid + compliant','Policy off')+act('hy17-access','helpdesk','Test Helpdesk sign-in')+act('hy17-access','finance','Test Finance sign-in')+(l.last?'<div class="hy17-output">'+H(l.last.target+': '+l.last.why)+'</div>':'')+(l.negative?'<div class="hy17-output">'+H(l.negative.target+': '+l.negative.why)+'</div>':'')+p('The lab uses a deliberately strict fictional policy. Real Conditional Access device conditions and grant controls are configured separately.'))+panel('5 · Validate configuration','<ul>'+criteria(l).map(c=>'<li>'+H((c[1]?'✓ ':'○ ')+c[0])+'</li>').join('')+'</ul>'+p(criteria(l).every(c=>c[1])?'Modeled onboarding passed. Now disable Alex, sync, and prove Helpdesk denial.':'Complete each criterion and retest both applications.')+(l.cloud&&!l.cloudEnabled&&l.last&&!l.last.allowed&&l.last.why==='Cloud account disabled'?'<div class="hy17-output">Modeled offboarding verified: cloud account disabled and Helpdesk denied.</div>':''))+panel('6 · Fault injection and evidence',p('Try PTA with agent unavailable, excluded sync scope, or a noncompliant device. Predict the result before testing. Restore correct settings and validate positive and negative cases.')+'<div class="hy17-log"><ol>'+l.logs.map(x=>'<li>'+H(x)+'</li>').join('')+'</ol></div>'+act('hy17-reset','reset','Reset only this fictional lab')));}
function audit(){let tests=[];const check=(name,pass)=>tests.push({name,pass:!!pass});check('15 unique modules',lessons.length===15&&new Set(lessons.map(l=>l[0])).size===15);for(const l of lessons){check(l[0]+' schema',l.length===13&&l[5].length>=5&&l[6].length===4&&l[10].length===3&&l[11]>=0&&l[11]<3);check(l[0]+' render',lesson(l).includes(H(l[9]))&&lesson(l).includes(H(l[7])));}check('home',home().includes('15 learning modules'));check('casebook',cases.length===8&&cases.every(c=>get(c[4])&&c[5][c[6]])&&casebook().includes('Hybrid diagnostic casebook'));check('unique vocabulary',new Set(vocab.map(t=>t.id)).size===vocab.length);const l=freshLab();check('no source blocks sync',!sync(l));l.user=true;check('excluded scope blocks sync',!sync(l));l.ou='Employees';l.dns=false;check('DNS failure blocks sync',!sync(l));l.dns=true;l.replication=false;check('replication failure blocks sync',!sync(l));l.replication=true;l.agent=false;check('agent failure blocks sync',!sync(l));l.agent=true;l.domain='unknown.example';check('unverified suffix blocks sync',!sync(l));l.domain='contoso.example';check('sync creates cloud identity',sync(l)&&l.cloud&&l.hash&&l.cloudEnabled);l.assignment='helpdesk';check('noncompliant device blocked',!access(l,'helpdesk').allowed);l.device='hybrid';l.compliant=true;check('helpdesk allowed',access(l,'helpdesk').allowed);check('finance denied for scope',!access(l,'finance').allowed&&l.negative.why==='Target app not assigned');check('onboarding meets criteria',criteria(l).every(c=>c[1]));change(l,'agent','false');check('configuration invalidates prior evidence',l.last===null&&l.negative===null);check('PHS works with current hash during modeled outage',access(l,'helpdesk').allowed);l.method='PTA';check('PTA fails during modeled outage',!access(l,'helpdesk').allowed);l.agent=true;l.method='PHS';l.enabled=false;check('offboarding requires sync',access(l,'helpdesk').allowed);check('disabled state exported',sync(l)&&!l.cloudEnabled);check('offboarded sign-in denied',!access(l,'helpdesk').allowed&&l.last.why==='Cloud account disabled');check('lab renders',lab().includes('Contoso hybrid identity simulator'));check('cards render',cards().includes('Vocabulary recall studio'));return {version:17,lessons:lessons.length,vocabulary:vocab.length,cases:cases.length,questions:lessons.length,passed:tests.filter(t=>t.pass).length,failed:tests.filter(t=>!t.pass).length,failures:tests.filter(t=>!t.pass),testType:'source, render and pure simulated-state checks; not actual browser or Microsoft tenant'};}
render=()=>{let r=current();if(!r.startsWith('v17/')){oldRender();return;}let out;if(r==='v17/lab')out=lab();else if(r==='v17/cards')out=cards();else if(r==='v17/cases')out=casebook();else if(r.startsWith('v17/lesson/')){let l=get(r.split('/').at(-1));if(l){s.last=l[0];persist();out=lesson(l);}else out=home();}else out=home();$('root').innerHTML=shell(out,r);document.title='Identity Academy · V17 Hybrid Engineering';lastRenderedHash=location.hash;};
action=(a,el)=>{let d=el?.dataset||{},id=d.id,n=Number(d.value),l=get(id),c=cases.find(x=>x[0]===id);if(a==='hy17-stage'&&l&&Number.isInteger(n)&&n>=0&&n<4)s.stages[id]=n;else if(a==='hy17-answer'&&l&&Number.isInteger(n)&&n>=0&&n<l[10].length)s.answers[id]=n;else if(a==='hy17-case'&&c&&Number.isInteger(n)&&n>=0&&n<c[5].length)s.cases[id]=n;else if(a==='hy17-card-mode'){filter=id;revealed='';cursor=0;}else if(a==='hy17-reveal'&&vocab.some(t=>t.id===id))revealed=id;else if(a==='hy17-rate'&&vocab.some(t=>t.id===id)){let prev=s.cards[id]?.interval||0;let interval=d.value==='good'?Math.min(30,Math.max(1,prev*2)):0;s.cards[id]={interval,due:Date.now()+interval*86400000};if(filter==='all'||d.value==='again')cursor++;revealed='';}else if(a==='hy17-config'){change(s.lab,id,d.value);}else if(a==='hy17-sync'){s.lab.last=null;s.lab.negative=null;sync(s.lab);}else if(a==='hy17-access'&&['helpdesk','finance'].includes(id))access(s.lab,id);else if(a==='hy17-reset'){s.lab=freshLab();}else{oldAction(a,el);return;}persist();render();};
document.addEventListener('submit',e=>{if(e.target?.id!=='hy17-note')return;e.preventDefault();if(get(e.target.dataset.id)){s.notes[e.target.dataset.id]=String(new FormData(e.target).get('note')||'').slice(0,8000);persist();toast('Reflection saved locally.');}});
window.__V17_TESTS={audit,lessons,cases,vocab,state:s,access,sync,change,criteria};
})();